SELECT CASE WHEN discount_pct >= 0.3 THEN 'HIGH' ELSE 'LOW' END AS discount_pct_tier, APPROX_PERCENTILE(discount_pct, 0.5) AS discount_pct_p50, COUNT(CASE WHEN channel = 'mobile' THEN 1 END) AS mobile_count, MAX(discount_pct) FILTER (WHERE channel = 'store') AS store_max_discount_pct, COUNT(CASE WHEN channel = 'store' THEN 1 END) AS store_count, MAX(discount_pct) FILTER (WHERE channel = 'web') AS web_max_discount_pct FROM promotions GROUP BY CUBE (CASE WHEN discount_pct >= 0.3 THEN 'HIGH' ELSE 'LOW' END)
